# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# run_modified_pars_fims ----
## Setup ----
# Load or prepare any necessary data for testing
data("data_big")
parameters <- setup_default_parameters(data = FIMSFrame(data_big))

## IO correctness ----
test_that("run_modified_pars_fims() works with correct inputs", {
  #' @description Skip the model fit unless explicitly enabled for heavy integration testing.
  testthat::skip_if(
    Sys.getenv("RUN_SLOW_TESTS") != "true",
    "Skipping: RUN_SLOW_TESTS is not set to true."
  )
  # inflection_point is a label in both the Maturity and Selectivity modules
  fit <- run_modified_pars_fims(
    new_value = 2.5,
    parameter_name = "inflection_point",
    module_name = "Maturity",
    parameters = parameters,
    data = data_big
  )
  inflection_point <- get_estimates(fit) |>
    dplyr::filter(label == "inflection_point")
  clear()

  #' @description Test that run_modified_pars_fims() changes only the parameter in the module given by module_name.
  expect_equal(
    object = inflection_point[["input"]][inflection_point[["module_name"]] == "Maturity"],
    expected = 2.5
  )
  #' @description Test that run_modified_pars_fims() leaves the same label in other modules unchanged.
  expect_equal(
    object = sort(inflection_point[["input"]][inflection_point[["module_name"]] == "Selectivity"]),
    expected = sort(dplyr::filter(
      parameters,
      module_name == "Selectivity",
      label == "inflection_point"
    )[["value"]])
  )
})

## Edge handling ----
test_that("run_modified_pars_fims() profiles a parameter that has a prior", {
  # 10 years of data_big keep the fit fast. Weight at age has 1 more year,
  # for the start of the year after the last model year.
  data_10_years <- data_big |>
    dplyr::filter(
      is.na(timing) |
        timing <= dplyr::if_else(type == "weight_at_age", 11, 10)
    ) |>
    FIMSFrame()
  # The recruitment log_sd and its prior both have a "log_sd" row in the
  # Recruitment module.
  parameters_with_prior <- setup_default_parameters(data_10_years) |>
    add_priors(
      log_sd ~ normal(mean = log(0.6), sd = 0.2),
      module_name = "Recruitment"
    )
  fit <- run_modified_pars_fims(
    new_value = log(0.5),
    parameter_name = "log_sd",
    module_name = "Recruitment",
    parameters = parameters_with_prior,
    data = data_10_years
  )
  log_sd <- get_estimates(fit) |>
    dplyr::filter(module_name == "Recruitment", label == "log_sd")
  #' @description Test that run_modified_pars_fims() takes a FIMSFrame and sets the parameter, not its prior's row with the same label.
  expect_equal(
    object = log_sd[["input"]],
    expected = log(0.5)
  )
  #' @description Test that run_modified_pars_fims() keeps the prior, scored at the profiled value, as the first likelihood component.
  expect_equal(
    object = get_report(fit)[["nll_components"]][[1]],
    expected = -stats::dnorm(log(0.5), log(0.6), 0.2, log = TRUE)
  )
})

## Error handling ----
test_that("run_modified_pars_fims() returns correct error messages", {
  #' @description Test that run_modified_pars_fims() errors when the label is not in the module given by module_name.
  expect_error(
    object = run_modified_pars_fims(
      new_value = 13,
      parameter_name = "log_rzero",
      module_name = "Selectivity",
      parameters = parameters,
      data = data_big
    ),
    regexp = "not found in parameters object"
  )

  #' @description Test that run_modified_pars_fims() errors when module_name and label match more than 1 parameter.
  expect_error(
    object = run_modified_pars_fims(
      new_value = 2,
      parameter_name = "inflection_point",
      module_name = "Selectivity",
      parameters = parameters,
      data = data_big
    ),
    regexp = "select a single parameter"
  )
})
